// MaxEco Node B.2: Load Active CRM Leads from Local Store / Dummy Seed
// Note: Uses sandboxed file read or returns test fixtures
const fs = require('fs');
const path = require('path');

const testDataPath = path.resolve(process.cwd(), 'automation/data/dummy-crm-leads.json');
let leads = [];

if (fs.existsSync(testDataPath)) {
  const raw = fs.readFileSync(testDataPath, 'utf8');
  const parsed = JSON.parse(raw);
  leads = parsed.testScenarios || [];
} else {
  leads = [
    {
      id: 'LEAD-FALLBACK-001',
      name: 'Default Test Lead',
      phone: '+91 99544 00000',
      service: 'Solar EPC',
      stage: 'Proposal Sent',
      nextFollowUpDate: new Date().toISOString().slice(0, 10),
      nextAction: 'Review technical feasibility'
    }
  ];
}

return leads.map(item => ({ json: item }));

// MaxEco Node B.4: Sorter & Days Overdue Calculator
const items = $input.all();
const todayStr = new Date().toISOString().slice(0, 10);
const todayMs = new Date(todayStr).getTime();

const enriched = items.map(item => {
  const lead = item.json;
  const fDate = lead.nextFollowUpDate || todayStr;
  const fMs = new Date(fDate).getTime();
  const diffDays = Math.floor((todayMs - fMs) / (1000 * 60 * 60 * 24));

  let urgencyLabel = 'DUE TODAY';
  if (diffDays > 0) {
    urgencyLabel = `OVERDUE (${diffDays} day${diffDays > 1 ? 's' : ''})`;
  }

  return {
    ...lead,
    daysOverdue: Math.max(0, diffDays),
    urgencyLabel
  };
});

// Sort oldest overdue first, then by deal value descending
enriched.sort((a, b) => (b.daysOverdue - a.daysOverdue) || (b.estimatedValue - a.estimatedValue));

return enriched.map(item => ({ json: item }));

// MaxEco Node B.5: Safe Digest Generator with Human-in-the-Loop WhatsApp Link
// CRITICAL: NEVER executes network requests or sends automated messages.
// Generates pre-formatted wa.me link for Founder 1-click review only.

const items = $input.all();
const todayStr = new Date().toISOString().slice(0, 10);

if (items.length === 0) {
  return [{
    json: {
      reportDate: todayStr,
      totalDue: 0,
      overdueCount: 0,
      summaryHtml: '<p><strong>All clear!</strong> No follow-ups are due today or overdue.</p>',
      leads: []
    }
  }];
}

let overdueCount = 0;
const leadCards = items.map(item => {
  const l = item.json;
  if (l.daysOverdue > 0) overdueCount++;

  // Sanitize phone to Indian standard (+91)
  const cleanPhone = (l.phone || '').replace(/[^0-9]/g, '');
  const waPhone = cleanPhone.startsWith('91') ? cleanPhone : ('91' + cleanPhone);

  // Pre-fill courteous inquiry draft in English/Assam context
  const draftText = `Hello ${l.contactPerson || l.name}, following up regarding your enquiry with MaxEco Energy & Tech for ${l.service}. Please let us know if you have any questions.`;
  const safeWaUrl = `https://wa.me/${waPhone}?text=${encodeURIComponent(draftText)}`;

  return {
    id: l.id,
    name: l.name,
    contactPerson: l.contactPerson,
    phone: l.phone,
    service: l.service,
    urgency: l.urgencyLabel,
    nextAction: l.nextAction,
    estimatedValue: l.estimatedValue,
    draftReviewUrl: safeWaUrl
  };
});

return [{
  json: {
    reportDate: todayStr,
    totalDue: items.length,
    overdueCount,
    generatedAt: new Date().toISOString(),
    leads: leadCards
  }
}];

// MaxEco Node B.6: Save Local Human-in-the-Loop HTML Report & Audit Log
const fs = require('fs');
const path = require('path');

const payload = $input.first().json;
const outDir = path.resolve(process.cwd(), 'docs/reports');
if (!fs.existsSync(outDir)) {
  fs.mkdirSync(outDir, { recursive: true });
}

const htmlContent = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>MaxEco Daily Follow-Up Digest - ${payload.reportDate}</title>
  <style>
    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; background: #0f172a; color: #f8fafc; padding: 24px; }
    .container { max-width: 800px; margin: 0 auto; }
    .badge { display: inline-block; padding: 4px 8px; border-radius: 4px; font-size: 11px; font-weight: bold; }
    .overdue { background: #ef4444; color: white; }
    .duetoday { background: #f59e0b; color: black; }
    .card { background: #1e293b; border: 1px solid #334155; border-radius: 8px; padding: 16px; margin-bottom: 12px; }
    .btn { display: inline-block; background: #25d366; color: white; padding: 8px 14px; text-decoration: none; border-radius: 6px; font-weight: bold; font-size: 12px; margin-top: 8px; }
  </style>
</head>
<body>
  <div class="container">
    <h2>MaxEco Energy & Tech - Daily Follow-Up Digest</h2>
    <p>Date: <strong>${payload.reportDate}</strong> | Total Follow-ups Due: <strong>${payload.totalDue}</strong> (Overdue: <strong>${payload.overdueCount}</strong>)</p>
    <p><em>Security Notice: Zero automated messages sent. Review each lead manually before contacting.</em></p>
    ${payload.leads.map(l => `
      <div class="card">
        <div style="display:flex; justify-content:space-between;">
          <strong>${l.name}</strong>
          <span class="badge ${l.urgency.includes('OVERDUE') ? 'overdue' : 'duetoday'}">${l.urgency}</span>
        </div>
        <div style="font-size:13px; color:#94a3b8; margin: 4px 0;">Service: ${l.service} | Value: ₹${(l.estimatedValue || 0).toLocaleString('en-IN')}</div>
        <div style="font-size:13px; margin-top: 6px;"><strong>Next Action:</strong> ${l.nextAction || 'Follow up'}</div>
        <a href="${l.draftReviewUrl}" target="_blank" class="btn">Open WhatsApp Review Draft</a>
      </div>
    `).join('')}
  </div>
</body>
</html>`;

const reportFilePath = path.join(outDir, `daily-digest-${payload.reportDate}.html`);
fs.writeFileSync(reportFilePath, htmlContent, 'utf8');

// Audit Log (scrubbed, zero customer personal data)
return [{
  json: {
    status: 'SUCCESS',
    reportDate: payload.reportDate,
    totalDue: payload.totalDue,
    overdueCount: payload.overdueCount,
    reportPath: reportFilePath,
    completedAt: new Date().toISOString()
  }
}];
